"""The robot description: parsed from `/robot_description`, never a file.

Spec 26.2. The agent subscribes the latched topic and serves the XML in the
handshake; this module turns it into something you can ask questions of.
Both sides use this parser — the agent to validate a profile's groups
against the robot at startup, the client to slice the chain it was given.

**Why the topic and not a path.** mod101's URDF is generated by the
configurator, so a path in a YAML can silently describe a different arm
than the one bolted on, and for a composed robot (base101 + mod101) it
cannot be accurate at all. The live topic is the only source that cannot
drift from what is actually moving. There is deliberately no
``from_file`` here, and profiles that name a ``urdf:`` are rejected.

Scope: structure and geometry as declared — links, joints, parents,
limits, axes, mounting offsets. No forward kinematics, no solver, no
numpy. Composing those offsets into a pose is 6.5's job, and it is an
optional extra; this parser is stdlib only, so `robot.description` costs
nothing to anyone who never asks for kinematics.

One trap worth naming: a URDF also carries ``<joint>`` elements *inside*
``<ros2_control>`` blocks, with the same names and no parent or child.
A walk that uses ``iter("joint")`` picks those up. Everything here uses
``findall`` on the root, and the ros2_control names are kept separately as
``hardware_joints`` — a tool joint may live only there.
"""

from __future__ import annotations

import hashlib
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field

__all__ = ["CollisionShape", "JointSpec", "RobotDescription", "sha_of"]

# Joint types that contribute a degree of freedom. "floating" and "planar"
# are excluded on purpose: they are not things a controller commands, and
# treating a planar root as three extra DOF is exactly the mistake spec
# 26.4 refuses to make.
MOVING_TYPES = frozenset({"revolute", "continuous", "prismatic"})


def sha_of(urdf: str) -> str:
    """The description's identity: sha256 of the exact bytes served.

    Compared rather than the XML itself, so a client can tell "same robot"
    from "rebuilt robot" in one cheap check on reconnect.
    """
    return hashlib.sha256(urdf.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class CollisionShape:
    """One ``<collision>`` volume on a link, in that link's frame.

    ``kind`` is the URDF primitive: box, cylinder, sphere, or mesh.
    ``half`` is the half-extent of the shape's bounding box — for a box
    that is exactly the shape, for a cylinder it is the smallest box
    containing it, and for a sphere the circumscribing cube.

    Meshes cannot be resolved from here: the file lives on the robot, and
    a client parsing a description it received over a socket has no way to
    open ``package://...``. Such a shape is carried with ``half`` of zero
    and ``mesh`` set, so a collision model can report the link as
    UNMODELLED rather than silently treating it as empty space.
    """

    link: str
    kind: str
    half: tuple[float, float, float]
    origin_xyz: tuple[float, float, float] = (0.0, 0.0, 0.0)
    origin_rpy: tuple[float, float, float] = (0.0, 0.0, 0.0)
    mesh: str | None = None
    # URDF `<mesh scale=>`. base101's meshes are authored in MILLIMETRES
    # and scaled by 0.001 here; ignoring it would model the jaws a
    # thousand times oversized and make every configuration collide.
    scale: tuple[float, float, float] = (1.0, 1.0, 1.0)

    @property
    def modelled(self) -> bool:
        """False for a mesh, whose extent is unknown to the client."""
        return self.mesh is None


@dataclass(frozen=True)
class JointSpec:
    """One joint as the URDF declares it.

    ``origin_xyz`` / ``origin_rpy`` are the fixed transform from the parent
    link to this joint's frame — the mounting offset. ``axis`` is the axis
    of motion in that frame, and is ``None`` for a fixed joint.
    """

    name: str
    type: str
    parent: str
    child: str
    origin_xyz: tuple[float, float, float] = (0.0, 0.0, 0.0)
    origin_rpy: tuple[float, float, float] = (0.0, 0.0, 0.0)
    axis: tuple[float, float, float] | None = None
    # (lower, upper) in radians or meters. None for a continuous joint,
    # which has no limit, and for anything that declares none.
    limits: tuple[float, float] | None = None
    effort: float | None = None
    velocity: float | None = None

    @property
    def moves(self) -> bool:
        """True if this joint contributes a degree of freedom."""
        return self.type in MOVING_TYPES


@dataclass(frozen=True)
class RobotDescription:
    """A parsed `/robot_description`.

    Build it with ``RobotDescription.parse(xml)``. The raw ``urdf`` is kept
    because the client may want to hand it to a solver, and because the
    ``sha`` has to be of the exact bytes that were served.
    """

    urdf: str
    sha: str
    name: str
    links: tuple[str, ...]
    joints: dict[str, JointSpec]
    # Joint names declared inside <ros2_control> blocks. Overlaps `joints`
    # for anything modelled; a tool joint may appear only here, because a
    # gripper can be commandable without its fingers being drawn.
    _hardware_joints: frozenset[str] = frozenset()
    # link -> its collision volumes. Links with no <collision> are absent;
    # they are usually pure frames (optical frames, IMU links) and have no
    # extent to collide with.
    collisions: dict[str, tuple[CollisionShape, ...]] = field(
        default_factory=dict, repr=False)
    # child link -> joint name, the index every upward walk uses.
    _parent_of: dict[str, str] = field(default_factory=dict, repr=False)

    @property
    def integration(self):
        """ros2_control declarations are integration provenance, not geometry."""
        from types import MappingProxyType
        return MappingProxyType({'hardware_joints':self._hardware_joints})

    # -- construction ------------------------------------------------------

    @classmethod
    def parse(cls, urdf: str) -> "RobotDescription":
        """Parse URDF XML. Raises ValueError on malformed input."""
        try:
            root = ET.fromstring(urdf)
        except ET.ParseError as exc:
            raise ValueError(f"robot description is not valid XML: {exc}") from exc

        links = tuple(
            link.get("name") for link in root.findall("link")
            if link.get("name")
        )
        joints: dict[str, JointSpec] = {}
        parent_of: dict[str, str] = {}
        for element in root.findall("joint"):
            spec = _joint_from(element)
            if spec is None:
                continue
            joints[spec.name] = spec
            parent_of[spec.child] = spec.name

        hardware = frozenset(
            joint.get("name")
            for block in root.iter("ros2_control")
            for joint in block.findall("joint")
            if joint.get("name")
        )
        collisions: dict[str, tuple[CollisionShape, ...]] = {}
        for element in root.findall("link"):
            name = element.get("name")
            if name is None:
                continue
            shapes = tuple(
                shape for shape in
                (_collision_from(name, c) for c in element.findall("collision"))
                if shape is not None
            )
            if shapes:
                collisions[name] = shapes
        return cls(
            urdf=urdf,
            sha=sha_of(urdf),
            name=root.get("name") or "robot",
            links=links,
            joints=joints,
            _hardware_joints=hardware,
            collisions=collisions,
            _parent_of=parent_of,
        )

    # -- structure ---------------------------------------------------------

    @property
    def root(self) -> str | None:
        """The link with no parent joint. None if the tree is empty."""
        for link in self.links:
            if link not in self._parent_of:
                return link
        return None

    @property
    def dof(self) -> int:
        """How many joints in the whole robot actually move."""
        return sum(1 for joint in self.joints.values() if joint.moves)

    def has_link(self, link: str) -> bool:
        return link in self.links

    def parent_joint(self, link: str) -> JointSpec | None:
        """The joint that attaches ``link`` to its parent, or None at the root."""
        name = self._parent_of.get(link)
        return None if name is None else self.joints[name]

    def children_of(self, link: str) -> tuple[str, ...]:
        """Links attached directly below ``link``, in declaration order."""
        return tuple(joint.child for joint in self.joints.values()
                     if joint.parent == link)

    def chain_to(self, link: str) -> tuple[str, ...]:
        """Joint names from the root down to ``link``, fixed ones included.

        Raises KeyError if ``link`` is not in the description. A malformed
        description with a cycle raises ValueError rather than hanging —
        this runs at agent startup, where a hang is worse than a crash.
        """
        if link not in self.links:
            raise KeyError(link)
        chain: list[str] = []
        current = link
        for _ in range(len(self.links) + 1):
            name = self._parent_of.get(current)
            if name is None:
                break                       # reached the root
            chain.append(name)
            current = self.joints[name].parent
        else:
            raise ValueError(
                f"the description has a cycle above link {link!r}")
        return tuple(reversed(chain))

    def moving_chain_to(self, link: str) -> tuple[str, ...]:
        """``chain_to`` with the fixed joints dropped — the DOF that
        actually place ``link``."""
        return tuple(name for name in self.chain_to(link)
                     if self.joints[name].moves)

    def is_downstream(self, link: str, of_joints: tuple[str, ...]) -> bool:
        """True if moving every one of ``of_joints`` moves ``link``.

        The check a group's ``tip`` has to pass. A tip on a sibling branch
        is a perfectly real link that parses fine and yields an end-effector
        pose which never changes — the failure this exists to prevent.
        """
        try:
            chain = frozenset(self.chain_to(link))
        except (KeyError, ValueError):
            return False
        return all(joint in chain for joint in of_joints)

    def subchain(self, joints: tuple[str, ...], tip: str) -> tuple[JointSpec, ...]:
        """The chain to ``tip``, sliced to the span the group owns.

        Everything from the group's first joint down to the tip, fixed
        joints included — those carry the mounting offsets, so dropping
        them would lose the geometry between one actuator and the next.
        Raises KeyError if the tip is unknown, ValueError if a declared
        joint is not on the way to it.
        """
        chain = self.chain_to(tip)
        missing = [joint for joint in joints if joint not in chain]
        if missing:
            raise ValueError(
                f"{', '.join(missing)} do not lie on the chain to {tip!r}")
        if not joints:
            return tuple(self.joints[name] for name in chain)
        first = min(chain.index(name) for name in joints)
        return tuple(self.joints[name] for name in chain[first:])

    def limits_of(self, joints: tuple[str, ...]
                  ) -> dict[str, tuple[float, float] | None]:
        """{joint: (lower, upper) | None} for the named joints."""
        return {name: self.joints[name].limits
                for name in joints if name in self.joints}


def _collision_from(link: str, element: ET.Element) -> CollisionShape | None:
    """One <collision> element as a bounding half-extent, or None.

    Cylinders and spheres are reduced to the box that contains them. That
    is deliberately conservative — it over-reports contact near a
    cylinder's corners by at most the circumscribing box — and it keeps
    the intersection test to a single case. Refine per-primitive only if a
    real robot loses reachable configurations to it.
    """
    geometry = element.find("geometry")
    if geometry is None:
        return None
    origin = element.find("origin")
    xyz = _triple(origin, "xyz", (0.0, 0.0, 0.0))
    rpy = _triple(origin, "rpy", (0.0, 0.0, 0.0))

    box = geometry.find("box")
    if box is not None:
        size = _numbers(box.get("size"), 3)
        if size is None:
            return None
        return CollisionShape(link, "box",
                              (size[0] / 2, size[1] / 2, size[2] / 2),
                              xyz, rpy)

    cylinder = geometry.find("cylinder")
    if cylinder is not None:
        radius = _maybe_float(cylinder.get("radius"))
        length = _maybe_float(cylinder.get("length"))
        if radius is None or length is None:
            return None
        return CollisionShape(link, "cylinder",
                              (radius, radius, length / 2), xyz, rpy)

    sphere = geometry.find("sphere")
    if sphere is not None:
        radius = _maybe_float(sphere.get("radius"))
        if radius is None:
            return None
        return CollisionShape(link, "sphere", (radius, radius, radius),
                              xyz, rpy)

    mesh = geometry.find("mesh")
    if mesh is not None:
        scale = _numbers(mesh.get("scale"), 3) or (1.0, 1.0, 1.0)
        return CollisionShape(link, "mesh", (0.0, 0.0, 0.0), xyz, rpy,
                              mesh=mesh.get("filename"), scale=scale)
    return None


def _numbers(raw: str | None, count: int) -> tuple[float, ...] | None:
    if not raw:
        return None
    parts = raw.split()
    if len(parts) != count:
        return None
    try:
        return tuple(float(v) for v in parts)
    except ValueError:
        return None


def _joint_from(element: ET.Element) -> JointSpec | None:
    """One <joint> element, or None if it is not a kinematic joint.

    Returns None for the ``<ros2_control>`` flavour, which has a name but
    no parent or child.
    """
    name = element.get("name")
    parent = element.find("parent")
    child = element.find("child")
    if name is None or parent is None or child is None:
        return None
    parent_link, child_link = parent.get("link"), child.get("link")
    if parent_link is None or child_link is None:
        return None

    kind = element.get("type") or "fixed"
    origin = element.find("origin")
    limit = element.find("limit")
    axis = element.find("axis")

    limits: tuple[float, float] | None = None
    effort = velocity = None
    if limit is not None:
        lower, upper = limit.get("lower"), limit.get("upper")
        # A continuous joint has no bounds by definition; anything else
        # missing one is treated the same way rather than half-bounded.
        if kind != "continuous" and lower is not None and upper is not None:
            limits = (float(lower), float(upper))
        effort = _maybe_float(limit.get("effort"))
        velocity = _maybe_float(limit.get("velocity"))

    return JointSpec(
        name=name,
        type=kind,
        parent=parent_link,
        child=child_link,
        origin_xyz=_triple(origin, "xyz", (0.0, 0.0, 0.0)),
        origin_rpy=_triple(origin, "rpy", (0.0, 0.0, 0.0)),
        axis=None if kind == "fixed" else _triple(axis, "xyz", (1.0, 0.0, 0.0)),
        limits=limits,
        effort=effort,
        velocity=velocity,
    )


def _triple(element: ET.Element | None, attribute: str,
            default: tuple[float, float, float]) -> tuple[float, float, float]:
    if element is None:
        return default
    raw = element.get(attribute)
    if not raw:
        return default
    parts = raw.split()
    if len(parts) != 3:
        return default
    try:
        return (float(parts[0]), float(parts[1]), float(parts[2]))
    except ValueError:
        return default


def _maybe_float(raw: str | None) -> float | None:
    if raw is None:
        return None
    try:
        return float(raw)
    except ValueError:
        return None
